add_filter( 'woocommerce_get_price_suffix', 'perfectpixel_price_both_taxes', 99, 4 );

function perfectpixel_price_both_taxes( $suffix, $product, $price, $qty ) {
	if ( ! wc_tax_enabled() || ! $product || $product->is_type( 'variable' ) || ! $product->is_taxable() ) {
		return $suffix;
	}
	$args = array( 'qty' => $qty ? $qty : 1, 'price' => '' === $price ? $product->get_price() : $price );
	if ( '' === $args['price'] ) {
		return $suffix;
	}
	if ( 'incl' === get_option( 'woocommerce_tax_display_shop' ) ) {
		$shown = esc_html( '{{price_incl_tax_label}}' );
		$other = wc_price( wc_get_price_excluding_tax( $product, $args ) ) . ' ' . esc_html( '{{price_excl_tax_label}}' );
	} else {
		$shown = esc_html( '{{price_excl_tax_label}}' );
		$other = wc_price( wc_get_price_including_tax( $product, $args ) ) . ' ' . esc_html( '{{price_incl_tax_label}}' );
	}
	return ' <span class="perfectpixel-tax-label">' . $shown . '</span> <span class="perfectpixel-other-price">&ndash; ' . $other . '</span>';
}
